from datetime import datetime

class ParkingMeter:
    def __init__(self, hourly_rate: float = 4.0) -> None:
        self.hourly_rate = hourly_rate

    def fee(self, entry: datetime, exit: datetime) -> float:
        if exit < entry:
            raise ValueError("exit time cannot be earlier than entry time")

        duration = exit - entry
        total_seconds = duration.total_seconds()

        if total_seconds > 24 * 3600:
            return round(200.00, 2)

        hours = total_seconds / 3600
        started_hours = int(hours)
        if hours > started_hours:
            started_hours += 1
        if started_hours == 0:
            started_hours = 1

        return round(started_hours * self.hourly_rate, 2)
